"""Decoded event records consumed by HttpClient in offline mode."""
from dataclasses import dataclass


class SendError(Exception):
    """A frame was attempted after the request send side already ended."""


class ConnectionClosed(Exception):
    """The captured connection terminated."""


@dataclass
class HeadersReceived:
    stream_id: int
    headers: list
    stream_ended: bool


@dataclass
class DataReceived:
    stream_id: int
    data: object
    stream_ended: bool


@dataclass
class ConnectionTerminated:
    error_code: int = 0
    reason_phrase: str = 'capture close'
